/// Explanations.
pub(super) const HELP: &[(&str, &str)] = &[
    ("menu.system-clock", "## O que faz\nMostra a hora e a data do roteador (UTC), de onde vieram (NTP, relógio da placa, nunca acertado) e o relógio da placa (RTC) ao lado, com quem o regrava. Só leitura: quem acerta o relógio é o System › NTP Client."),
    ("ntp.clock", "## O que é\nO que o cliente está fazendo com o relógio do sistema.\n\n- `slewing`: a diferença é pequena (abaixo de 128 ms) e o relógio anda um pouco mais rápido ou mais devagar até zerá-la, sem saltos.\n- `stepped`: a última resposta acertou o relógio de uma vez.\n- `holding-spike`: um relógio já certo recebeu uma diferença grande; fica como está por até 900 s, para o caso de ser uma resposta errada (RFC 5905 §11.3).\n- `awaiting-confirmation`: a diferença passa de 1000 s e só muda com a sua confirmação.\n- `refused`: a resposta levaria o relógio para antes de 2026 e nunca é aplicada.\n- `not-set`: só mede: desligado em Set System Clock, ou este backend ou processo não pode mexer no relógio (o motivo aparece em Clock Error)."),
    ("ntp.clock_date", "## O que é\nA data do roteador, em UTC (ano-mês-dia, como o RouterOS 7)."),
    ("ntp.clock_error", "## O que é\nPor que o relógio não pôde ser mudado. O caso comum é o processo não ter `CAP_SYS_TIME`, ou o laboratório virtual, que nunca mexe no relógio do computador onde roda."),
    ("ntp.clock_hardware", "## O que é\nO relógio da placa (RTC), que tem bateria e guarda a hora com o roteador desligado. O kernel o lê no boot como UTC, e é dele que vem a hora antes do NTP.\n\n- A diferença entre parênteses é RTC menos o relógio do sistema.\n- `follows-system`: instalado e sincronizado, o kernel regrava o RTC a cada ~11 min.\n- `left-alone`: a imagem live nunca regrava o RTC, para não mudar a hora de outro sistema da máquina (G4.6o).\n- `not-written`: ninguém regravou o RTC nesta execução.\n\n## Hora local\nUma diferença de fuso inteiro (−03:00, por exemplo) quer dizer que o RTC está em hora local, como o Windows o mantém. Num roteador só com o CoreRouter, o RTC em UTC é o certo."),
    ("ntp.clock_now", "## O que é\nA hora do roteador agora e de onde ela veio. Detalhes em System › Clock."),
    ("ntp.clock_source", "## O que é\nDe onde veio a hora do roteador.\n\n- `ntp`: o cliente NTP acertou o relógio (servidor e quando, abaixo).\n- `rtc`: a hora com que o sistema bootou, lida do relógio da placa e não corrigida desde então.\n- `host`: o laboratório virtual mostra a hora do computador em que roda.\n- `not-set`: antes de 2026, o relógio nunca foi acertado (placa sem bateria e sem resposta NTP)."),
    ("ntp.clock_time", "## O que é\nA hora do roteador, em UTC. É a hora dos logs, do journal e dos certificados."),
    ("ntp.clock_time_zone", "## O que é\nO fuso usado para mostrar a hora. Por enquanto o roteador não tem fuso configurável: tudo é UTC, como o kernel e os logs."),
    ("ntp.dynamic_servers", "## O que é\nServidores recebidos de clientes DHCP com `use_peer_ntp` (opção 42 do DHCPv4, 56 do DHCPv6), usados depois dos configurados. No máximo 8 ao todo."),
    ("ntp.enabled", "## O que faz\nLiga o cliente NTP.\n\n## Padrão\nLigado num roteador novo (config nunca gravada), sem servidor configurado: ele pergunta só aos servidores que o DHCP da rede entregar (opção 42, ou a 56 no DHCPv6) e a mais ninguém. Numa config já gravada vale o que está nela.\n\n## Cuidado\nCom Set System Clock ligado, ele passa a mandar no relógio do sistema."),
    ("ntp.freq_drift", "## O que é\nQuanto o cristal deste roteador erra, aprendido medida após medida. Positivo: o cristal é lento. Volta a zero quando o serviço reinicia e é reaprendido em poucas consultas."),
    ("ntp.last_adjustment", "## O que é\nO tamanho da última correção, por slew ou salto."),
    ("ntp.last_error", "## O que é\nPor que a última consulta falhou, uma linha por servidor."),
    ("ntp.last_sync", "## O que é\nQuando chegou a última resposta boa."),
    ("ntp.max_poll", "## O que é\nMaior intervalo entre consultas, em potência de 2 segundos: 10 = 17 min. O intervalo dobra a cada resposta boa até aqui."),
    ("ntp.min_poll", "## O que é\nMenor intervalo entre consultas, em potência de 2 segundos: 6 = 64 s. Abaixo disso a RFC 4330 §5 não permite."),
    ("ntp.next_poll", "## O que é\nQuando vem a próxima consulta."),
    ("ntp.round_trip", "## O que é\nIda e volta até o servidor. O erro da medida é no máximo metade disso (RFC 5905 §8)."),
    ("ntp.server.allowed", "## O que é\nQuem pode perguntar a hora, um item por linha: um prefixo (`192.168.0.0/16`), um intervalo (`10.0.0.1-10.0.0.9`) ou o nome de uma **address-list** do firewall, com as entradas fixas e as dinâmicas (IP › Firewall › Address Lists). Quem está fora não recebe nada, nem recusa.\n\n## Lista sem entradas\nNão libera ninguém e aparece em Empty Lists. Uma entrada nova vale em até 2 s, sem mexer aqui.\n\n## Padrão\nLoopback, link-local e redes privadas (como o VyOS), então um endereço público da WAN nunca responde por acidente. A lista vazia não responde a ninguém.\n\n## Cuidado\nLibere endereços públicos só com motivo. NTP aberto é alvo de abuso (RFC 8633 §5.1)."),
    ("ntp.server.broadcast", "## O que faz\nEnvia a hora a cada 64 s para Broadcast Addresses (modo 5), sem o cliente pedir.\n\n## Cuidado\nNada autentica essas mensagens: use só numa rede de confiança (RFC 8633 §5.5). Desligado por padrão."),
    ("ntp.server.broadcast_addresses", "## O que é\nOs endereços de broadcast das sub-redes (`192.168.88.255`), não o de um host. Só IPv4."),
    ("ntp.server.denied", "## O que é\nPerguntas de fora de Allowed, ignoradas em silêncio."),
    ("ntp.server.empty_lists", "## O que é\nAddress-lists citadas em Allowed que estão vazias ou não existem. Elas não liberam ninguém: confira o nome."),
    ("ntp.server.enabled", "## O que faz\nLiga o servidor NTP (porta UDP 123). Desligado por padrão.\n\n## Importante\nSó responde depois que o cliente NTP sincronizou, ou com Use Local Clock. Até lá fica em silêncio, para não espalhar hora errada."),
    ("ntp.server.kisses", "## O que é\nAvisos Kiss-o'-Death RATE enviados a quem perguntou demais (RFC 5905 §7.4): no máximo um a cada 10 s por origem."),
    ("ntp.server.last_error", "## O que é\nPor que não abriu a porta. O caso comum é outro serviço já usando a UDP 123."),
    ("ntp.server.limited", "## O que é\nPerguntas acima do limite, depois do aviso, ignoradas em silêncio."),
    ("ntp.server.local_clock_stratum", "## O que é\nO stratum anunciado para o relógio local, de 1 a 15.\n\n## Padrão\n5, como no RouterOS. Use um valor alto, para o cliente preferir qualquer fonte de verdade."),
    ("ntp.server.malformed", "## O que é\nDatagramas que não são pergunta (modos 6 e 7 inclusive, RFC 9327 §6) ou vêm de origem inválida, ignorados em silêncio."),
    ("ntp.server.rate_limit", "## O que faz\nLimita cada origem a uma média de uma pergunta a cada 2 s, com folga de 16 (IPv6 conta por /64). Acima disso manda um Kiss-o'-Death RATE (RFC 5905 §7.4) e depois fica em silêncio.\n\n## Quando desligar\nSó com muitos clientes atrás de um único endereço.\n\n## Padrão\nLigado."),
    ("ntp.server.replies", "## O que é\nRespostas enviadas."),
    ("ntp.server.requests", "## O que é\nPerguntas bem formadas de origens permitidas."),
    ("ntp.server.serving", "## O que é\nDe quem é a hora que o servidor dá.\n\n- `upstream`: a do servidor com que o cliente sincronizou. Sem resposta, continua enquanto a incerteza acumulada ficar abaixo de 1 s (cerca de 18 h).\n- `local-clock`: a do relógio deste roteador (Use Local Clock).\n- `no`: nenhuma; fica em silêncio."),
    ("ntp.server.stratum", "## O que é\nO stratum anunciado: o do servidor de cima mais 1, ou Local Clock Stratum."),
    ("ntp.server.unsynchronized", "## O que é\nPerguntas recebidas enquanto o relógio não estava bom, ignoradas em silêncio."),
    ("ntp.server.use_local_clock", "## O que faz\nDá a hora do relógio deste roteador quando não há fonte melhor.\n\n## Cuidado\nO relógio local deriva sem correção: os clientes recebem hora que parece boa e pode estar errada. Use em rede isolada, sem acesso a servidor NTP. O cliente mostra `using-local-clock`."),
    ("ntp.server.vrf", "## O que é\nEm qual VRF o servidor escuta. `main` é a tabela principal."),
    ("ntp.servers", "## O que é\nUm por linha: endereço IP ou nome DNS (`pool.ntp.org`). O cliente pergunta a todos e fica com a resposta de menor ida e volta.\n\n## Quando pode ficar vazio\nQuando um cliente DHCP com `use_peer_ntp` traz os servidores (Dynamic Servers). Sem nenhum dos dois o cliente espera, e a verificação de saúde avisa \"relógio não ajustado\"."),
    ("ntp.set_system_clock", "## O que faz\nAplica ao relógio do sistema o que foi medido. Abaixo de 128 ms por slew, acima por salto; acima de 1000 s pede confirmação.\n\n## Quando desligar\nNum computador comum onde chrony ou timesyncd já cuidam do relógio: dois donos brigam. O RouterOS não tem essa opção.\n\n## Padrão\nLigado. Precisa do backend linux e de `CAP_SYS_TIME`."),
    ("ntp.status", "## O que é\n`synchronized`: a última consulta teve resposta boa. `waiting`: ligado, sem resposta boa. `stopped`: desligado, ou nenhum daemon roda o cliente."),
    ("ntp.synced_server", "## O que é\nO servidor da medida em uso e o endereço dele."),
    ("ntp.synced_stratum", "## O que é\nA distância do servidor até a fonte de hora: 1 é ligado a um relógio de referência, 2 pergunta a um stratum 1, e assim por diante."),
    ("ntp.system_offset", "## O que é\nA hora do servidor menos a nossa, na última medida. Positivo: o nosso relógio está atrasado."),
    ("ntp.vrf", "## O que é\nEm qual VRF os servidores são alcançados. `main` é a tabela principal. Fora dela o socket é preso ao VRF (`SO_BINDTODEVICE`).\n\n## Limite\nNomes DNS são resolvidos pelo resolvedor do roteador, que usa a tabela principal."),
];
